UPDATE email_fragments SET fragment = '<tr><td style="background-color: #f5f5f5; padding: 24px; text-align: center; font-family: Arial, Helvetica, sans-serif; font-size: 12px; color: #777777;"><p style="margin: 0;">© 2026 LMT</p><p style="margin: 8px 0 0 0;">Ta wiadomość została wygenerowana automatycznie. Prosimy na nią nie odpowiadać.</p><p style="margin: 8px 0 0 0;">W razie pytań skontaktuj się z nami:<a href="mailto:${contactEmail}" style="color: #777777;">${contactEmail}</a>lub telefonicznie pod numerem<a href="tel:${contactNumber}" style="color: #777777;">${contactNumber}</a>.</p></td></tr>' WHERE name = 'Footer pl';
UPDATE email_fragments SET fragment = '<tr><td style="background-color: #f5f5f5; padding: 24px; text-align: center; font-family: Arial, Helvetica, sans-serif; font-size: 12px; color: #777777;"><p style="margin: 0;">© 2026 LMT</p><p style="margin: 8px 0 0 0;">This message was generated automatically. Please do not reply to it.</p><p style="margin: 8px 0 0 0;">If you have any questions, please contact us at<a href="mailto:${contactEmail}" style="color: #777777;">${contactEmail}</a>or call us at<a href="tel:${contactNumber}" style="color: #777777;">${contactNumber}</a>.</p></td></tr>' WHERE name = 'Footer en';

UPDATE email_fragments SET fragment = '<tr> <td style="background-color: #ffffff; padding: 40px; font-family: Arial, Helvetica, sans-serif; color: #333333;"> <p>Witaj ${nick},</p><p>Utworzono rezerwacje w ${roomName} sali dla zespołu ${organizationName}</p><p>Rozpoczęcie: <strong>${startAt}</strong></p><p>Zakończenie: <strong>${endAt}</strong></p><p>Życzymy udanego grania!</p></td> </tr>' WHERE name = 'Reservation Created Organization pl';
UPDATE email_fragments SET fragment = '<tr> <td style="background-color: #ffffff; padding: 40px; font-family: Arial, Helvetica, sans-serif; color: #333333;"> <p>Hello ${nick},</p><p>A reservation has been created in the ${roomName} room for the band ${organizationName}.</p><p>Start time: <strong>${startAt}</strong></p><p>End time: <strong>${endAt}</strong></p><p>We wish you a great jam session!</p></td> </tr>' WHERE name = 'Reservation Created Organization en';